import StyleDictionary from "style-dictionary";
import { register } from "@tokens-studio/sd-transforms";
import { readFile, writeFile, mkdir } from "node:fs/promises";

/**
 * Use the Tokens Studio preprocessor plugin to avoid broken references when working with Tokens Studio JSON.
 *
 * Design Tokens JSON generated by Tokens Studio contains an additional layer in the JSON for the names of "Token Sets".
 * Use the `excludeParentKeys` option to exclude this layer from the output, and avoid broken references.
 * Without this plugin the references would look like `"$value": "{common.basis.text.line-height.md}"` instead of `"$value": "{basis.text.line-height.md}"`.
 */
register(StyleDictionary, {
  excludeParentKeys: true,
});

const removeDarkMode = (dictionary) =>
  Object.keys(dictionary).forEach((key) => {
    console.log(key);
    if (key.startsWith("color-scheme-dark/")) {
      console.log(`Removing dark mode token: ${key}`);
      /* eslint-disable-next-line @typescript-eslint/no-dynamic-delete */
      delete dictionary[key];
    }
  });

// const themeConfig = JSON.parse(await readFile("./config.json", "utf-8"));

const createThemeConfig = ({ buildPath }) => {
  return {
    source: ["src/**/*.tokens.json"],
    preprocessors: ["tokens-studio"],
    log: {
      verbosity: "verbose",
    },
    platforms: {
      css: {
        transformGroups: "tokens-studio",
        transforms: ["name/kebab"],
        buildPath,
        files: [
          {
            destination: "theme.css",
            format: "css/variables",
            options: {
              selector: ".fdnd-theme",
              outputReferences: true,
            },
          },
          {
            destination: "variables.css",
            format: "css/variables",
            options: {
              selector: ":root",
              outputReferences: true,
            },
          },
        ],
      },
    },
  };
};

// verwijder de darkmode tokens uit de json en geef deze mee aan de lightmode
const colorSchemeDefaultPreprocessor = {
  name: "color-scheme-default",
  preprocessor(tokensJSON) {
    removeDarkMode(tokensJSON);
    return tokensJSON;
  },
};

StyleDictionary.registerPreprocessor(colorSchemeDefaultPreprocessor);

// maak twee builds aan, een voor de lightmode en een voor de darkmode en zet dit in een tmp (temporary) map
const sdLight = new StyleDictionary({
  ...createThemeConfig({ buildPath: "tmp/light-mode/" }),

  preprocessors: [colorSchemeDefaultPreprocessor.name, "tokens-studio"],
});
await sdLight.buildAllPlatforms();

const sdDark = new StyleDictionary({
  ...createThemeConfig({ buildPath: "tmp/dark-mode/" }),
});
await sdDark.buildAllPlatforms();

// aanmaken van de dist map
await mkdir("dist/");

const css = (strings) => strings.join("");

// zoek de light en dark mode css bestanden en lees deze uit
const cssDark = await readFile("./tmp/dark-mode/variables.css", "utf-8");
const cssLight = await readFile("./tmp/light-mode/variables.css", "utf-8");

// zet de lightmode in een de cssVariables, voeg een @media voor darkmode toe en zet daar de darkmode css in
let cssVariables = css`
  /* light mode here */

  @media (prefers-color-scheme: dark) {
    /* dark mode here */
  }
`
  .replace("/* light mode here */", cssLight)
  .replace("/* dark mode here */", cssDark);

// voer de commando' in cssVariables uit en zet het in de dist map in het variables.css bestand
await writeFile("./dist/variables.css", cssVariables);
